function gapTotals(nums: number[]): number[] {
  const n = nums.length;
  const out = new Array(n).fill(0);
  for (let i = 0; i < n; i++)
    for (let j = 0; j < n; j++)
      if (nums[i] === nums[j]) out[i] += Math.abs(i - j);
  return out;
}

