function gapTotals(nums: number[]): number[] {
  const groups = new Map<number, number[]>();
  nums.forEach((v, i) => {
    const g = groups.get(v);
    if (g) g.push(i);
    else groups.set(v, [i]);
  });
  const out = new Array(nums.length).fill(0);
  for (const pos of groups.values()) {
    const m = pos.length;
    let total = 0;
    for (const p of pos) total += p;
    let prefix = 0;
    for (let k = 0; k < m; k++) {
      const p = pos[k];
      const left = k * p - prefix;
      const right = (total - prefix - p) - (m - 1 - k) * p;
      out[p] = left + right;
      prefix += p;
    }
  }
  return out;
}

